// app/api/reminders/route.ts
import { NextResponse } from 'next/server';
import prisma from '@/lib/prisma/client';
import { smsQueue } from '@/lib/queue/bullmq';
import { randomUUID } from 'crypto';
import { utcToZonedTime, format } from 'date-fns-tz';

// This endpoint is hit by a cron (e.g., Upstash QStash) every minute.
// It scans for reminders that should fire now and enqueues SMS jobs.
export async function GET() {
  const now = new Date();

  // Find all reminders where the next scheduled time is <= now
  const dueReminders = await prisma.reminder.findMany({
    where: {
      nextRun: {
        lte: now,
      },
    },
    include: {
      medication: true,
      user: true,
    },
  });

  for (const r of dueReminders) {
    const message = `💊 ${r.medication.name} (${r.medication.dosage}) - ${format(
      utcToZonedTime(r.nextRun, r.user.timeZone),
      'HH:mm'
    )}`;

    await smsQueue.add('sendSms', {
      phone: r.user.phone,
      message,
      provider: 'twilio', // primary – fallback handled inside SmsService
    });

    // Compute next Run (daily recurrence for simplicity)
    const next = new Date(r.nextRun);
    next.setDate(next.getDate() + 1);
    await.reminder.update({
      where: { id: r.id },
      data: { nextRun: next },
    });
  }

  return NextResponse.json({ enqueued: dueReminders.length });
}
